        a=json.loads(text)['items']; return [(int(x['prod_id'][2:]),int(x['qty' if kind=='order' else 'delivered_qty'])) for x in a]
    if path.endswith('.csv'):
        rows=csv.DictReader(text.splitlines(),delimiter=';'); return [(int(x['PRODUCT'][2:]),int(x['QUANTITY' if kind=='order' else 'DELIVERED_QTY'])) for x in rows]
    if kind=='order':
        if 'ORDER_PRODUCT' in text: pat=r'ORDER_PRODUCT:\s*P_(\d+)\s*\|\s*ORDER_QTY:\s*(\d+)'
        else: pat=r'deliver\s+(\d+)\s+units of product P_(\d+)'; return [(int(p),int(q)) for q,p in re.findall(pat,text)]
    else:
        if re.search(r'^PRODUCT:',text,re.M): pat=r'PRODUCT:\s*P_(\d+)\s*\|\s*DELIVERED_QTY:\s*(\d+)'
        else: pat=r'delivered\s+(\d+)\s+units of product P_(\d+)'; return [(int(p),int(q)) for q,p in re.findall(pat,text)]
    return [(int(p),int(q)) for p,q in re.findall(pat,text)]
orders={}
for f in glob.glob('raw_orders/*'):
 m=re.search(r'day_(\d+)_S_(\d+)',f); orders[(int(m.group(1)),int(m.group(2)))]=parse_items(f,'order')
supp={}
for f in glob.glob('raw_supplier_receipts/*'):
 m=re.search(r'day_(\d+)_PR_(\d+)',f); supp[(int(m.group(1)),int(m.group(2)))]=parse_items(f,'supp')
sseq=collections.defaultdict(list)
for f in glob.glob('raw_wholesaler_receipts/*'):
 t=open(f).read(); d=int(re.search(r'DAY:\s*(\d+)',t).group(1)); pr=int(re.search(r'SUPPLIER_ID:\s*PR_(\d+)',t).group(1)); seq=int(re.search(r'DAILY_SEQUENCE_NO:\s*(\d+)',t).group(1)); sseq[d].append((seq,pr))
stseq=collections.defaultdict(list); expected={}
for f in glob.glob('raw_wholesaler_store_receipts/*'):
 t=open(f).read(); d=int(re.search(r'DAY:\s*(\d+)',t).group(1)); s=int(re.search(r'STORE_ID:\s*S_(\d+)',t).group(1)); seq=int(re.search(r'DAILY_SEQUENCE_NO:\s*(\d+)',t).group(1)); total=int(re.search(r'TOTAL_DELIVERED_UNITS:\s*(\d+)',t).group(1)); stseq[d].append((seq,s)); expected[d,s]=total
print('parsed',len(orders),len(supp),sum(map(len,sseq.values())),sum(map(len,stseq.values())))
print('item lens orders',collections.Counter(map(len,orders.values())).most_common(8),'supp',collections.Counter(map(len,supp.values())).most_common(8))
# aggregate inventory sim, suppliers first
inv=collections.Counter(); mism=[]
for d in range(1,366):
 for _,pr in sorted(sseq[d]):
  for p,q in supp[d,pr]: inv[p]+=q
 for _,s in sorted(stseq[d]):
  tot=0
  for p,q in orders.get((d,s),[]):
   z=min(q,inv[p]); inv[p]-=z; tot+=z
  if tot!=expected[d,s]: mism.append((d,s,tot,expected[d,s]))
print('suppliers then stores mismatches',len(mism),mism[:20], 'end inv',sum(inv.values()))
# stores first variant
inv=collections.Counter(); mism=[]
for d in range(1,366):
 for _,s in sorted(stseq[d]):
  tot=0
  for p,q in orders.get((d,s),[]):
   z=min(q,inv[p]); inv[p]-=z; tot+=z
  if tot!=expected[d,s]: mism.append((d,s,tot,expected[d,s]))
 for _,pr in sorted(sseq[d]):
  for p,q in supp[d,pr]: inv[p]+=q
print('stores then suppliers mismatches',len(mism),mism[:10])
print('store populations')
# group count first day
prev=None; lastp=0; idx=0
with open('sales_log.csv',newline='') as f:
 for r in csv.DictReader(f):
  d=int(r['Day']);s=int(r['Store_ID'][2:]);p=int(r['Product_ID'][2:]); key=d,s
  if key!=prev:
   if prev and prev[0]==1: print(prev[1],idx+1)
   if d>1: break
   idx=0;lastp=0;prev=key
  elif p<=lastp:idx+=1
  lastp=p
PY","workdir":"/app","yield_time_ms":30000,"max_output_tokens":10000});
text(r.output);

