  return [(int(p),int(q)) for q,p in re.findall(r'deliver\s+(\d+)\s+units of product P_(\d+)',t)]
 if re.search(r'^PRODUCT:',t,re.M): return [(int(p),int(q)) for p,q in re.findall(r'PRODUCT:\s*P_(\d+)\s*\|\s*DELIVERED_QTY:\s*(\d+)',t)]
 return [(int(p),int(q)) for q,p in re.findall(r'delivered\s+(\d+)\s+units of product P_(\d+)',t)]
orders={}
for f in glob.glob('raw_orders/*'):
 m=re.search(r'day_(\d+)_S_(\d+)',f); orders[int(m[1]),int(m[2])]=parse_items(f,'o')
supp={}
for f in glob.glob('raw_supplier_receipts/*'):
 m=re.search(r'day_(\d+)_PR_(\d+)',f); supp[int(m[1]),int(m[2])]=parse_items(f,'s')
sseq=collections.defaultdict(list)
for f in glob.glob('raw_wholesaler_receipts/*'):
 t=open(f).read(); sseq[int(re.search(r'DAY:\s*(\d+)',t)[1])].append((int(re.search(r'DAILY_SEQUENCE_NO:\s*(\d+)',t)[1]),int(re.search(r'SUPPLIER_ID:\s*PR_(\d+)',t)[1])))
stseq=collections.defaultdict(list)
for f in glob.glob('raw_wholesaler_store_receipts/*'):
 t=open(f).read(); stseq[int(re.search(r'DAY:\s*(\d+)',t)[1])].append((int(re.search(r'DAILY_SEQUENCE_NO:\s*(\d+)',t)[1]),int(re.search(r'STORE_ID:\s*S_(\d+)',t)[1])))
# batch-aware wholesaler allocation
winv=[collections.deque() for _ in range(31)]
deliv=collections.defaultdict(lambda:collections.defaultdict(lambda:collections.defaultdict(list)))
for d in range(1,366):
 for _,pr in sorted(sseq[d]):
  for p,q in supp[d,pr]: winv[p].append([pr,q,d])
 for _,s in sorted(stseq[d]):
