sinv={(s,p):collections.deque() for s in range(1,11) for p in range(1,31)}
events=[]; mism=0; nrows=0
prevkey=None; prevp=0;ci=0; loaded=set()
with open('sales_log.csv',newline='') as f:
 for r in csv.DictReader(f):
  d=int(r['Day']);s=int(r['Store_ID'][2:]);p=int(r['Product_ID'][2:]); y=int(r['Reported_Demand']); sold=int(r['Sold_Quantity']);key=(d,s)
  if key not in loaded:
   # deliveries from prior day become available
   if d>1:
    for pp,batches in deliv[d-1][s].items():
     sinv[s,pp].extend([list(x) for x in batches])
   loaded.add(key)
  if key!=prevkey: ci=0;prevp=0;prevkey=key
  elif p<=prevp:ci+=1
  prevp=p; g=off[s]+ci;Y[d,g,p-1]=y;Sold[d,g,p-1]=sold;nrows+=1
  q=sold; src=[]
  while q:
   if not sinv[s,p]: mism+=1;break
   pr,zq,bd=sinv[s,p][0];take=min(q,zq);src.append((pr,take,bd));q-=take;zq-=take
   if zq:sinv[s,p][0][1]=zq
